        "passage": "Imagine having a medical appointment without leaving your home. Thanks to telemedicine, this is now possible: patients speak to doctors by video call, send photographs of their symptoms and receive prescriptions online. The service has grown rapidly in recent years, especially in areas where the nearest hospital is hours away.\n\nFor people in remote villages, the benefits can be life-changing. A farmer who once had to spend a day travelling to the district hospital can now consult a specialist from a local health station, saving time, money and sometimes lives. Patients who use such services regularly are often more likely to keep their appointments than <b>those</b> who must travel far. <u>Doctors also appreciate that routine check-ups can be handled quickly, leaving more time for urgent cases.</u>\n\nHowever, telemedicine has clear limits. A doctor cannot listen to a patient's heart through a screen or examine a swelling by touch. Poor internet connections can make the consultation <b>frustrating</b> or even impossible, and elderly patients who are not used to technology may feel uncomfortable.\n\nDespite these problems, experts believe that telemedicine will become a permanent part of healthcare. The most <b>promising</b> model combines remote and face-to-face care: simple problems are handled online, while serious cases are directed to hospitals. If supported by reliable internet and clear privacy rules, such a system could bring good healthcare to millions more people."
