        "passage": "A smart city uses sensors, cameras and data networks to manage its services more efficiently. Traffic lights adjust to the number of cars on the road, street lamps dim when no one is nearby, and rubbish bins signal when they need to be emptied. These systems save energy and money, and they make daily life more <b>convenient</b> for residents.\n\nBehind these benefits, however, lies a large amount of personal data. Cameras can record where people go, and mobile apps can track how long they stay. <u>When such information is collected on a massive scale, it can reveal intimate details of people's habits, health and relationships.</u> Residents are often unaware of how much is being recorded or who can see it.\n\n[I] Privacy experts therefore call for clear rules. [II] They argue that cities should explain what data they collect and for what purpose. [III] Data should be stored securely and deleted when it is no longer needed. [IV] Citizens should also have the right to ask what information is held about them.\n\nSome cities have shown that smart technology and privacy can coexist. They collect only the data they really need, remove names from records and publish annual reports about how information is used. Residents who trust their city are more likely to support new projects than <b>those</b> who feel watched. In the end, a truly smart city is one in which technology serves its citizens, not the other way round."
