        "answer": 3,
        "passage": "As ASEAN countries become more closely connected, young people in the region face both new opportunities and new demands. Companies now seek employees who can work across borders, communicate in English and understand different cultures. At the same time, universities in the region are developing partnership programmes that allow students to spend a semester abroad.\n\nLanguage skills are particularly important. English is the working language of ASEAN, and young people who can use it confidently find it easier to join regional projects than <b>those</b> who cannot. <u>Learning the language of a neighbouring country, such as Thai, Malay or Indonesian, can give a student a further advantage and show genuine respect for other cultures.</u> Online platforms make it easy to begin.\n\nHowever, opportunities are not equally available to everyone. Students in rural areas may have limited access to good teachers, reliable internet or scholarships. Families with low incomes may find it difficult to pay for study abroad, even for short periods. Governments and schools therefore need to ensure that programmes are <b>accessible</b> to young people from every background.\n\nYoung people can also take the initiative. Joining student clubs, online forums or volunteer projects that involve other countries allows them to practise language skills and to build friendships that may last a lifetime. Such experiences prepare them to <b>contribute</b> to a region in which cooperation will matter more and more."
